/*
* 影片·新港 - 酒馆主题美化
* 代码来源：基于墨千尾老师的css代码，部分来自dc教程区的老师们，太多了尽量标注上。
本代码分为两个部分，前半段为教程楼的基础代码，后半段是玲自己跑的
教程链接：https://discord.com/channels/1291925535324110879/1380392618336194702
墨千尾的基础美化框架：
https://discord.com/channels/1291925535324110879/1422717884378910801
* 二创作者：玲
* 素材来源于网络。
* 改适配看🧧（我有点懒得改，可以直接问ai你要改哪里）
此为宽屏美化！
如果你不需要头像效果可以搜索“头像效果”这四个字来改
（css关键词搜“第一步”开始）
适配教程补充：
第一步修改气泡宽度让气泡适配你的屏幕
第二步和第三步都在一起。
后续你们根据以下关键词去改：头像容器（看见🔴和🧧就对了）、计时器、楼层、token、时间戳左右、名字水平位置、文本顶部留空、正文盒子宽度、影响下边距、这第三个数字是下边距（正文底部留空）、思维链位置（思维链左右位置）、编辑消息图标（小铅笔）。
图标有问题的看群精华。
*/
/*字体🛑*/
@import url("https://fontsapi.zeoseven.com/376/main/result.css");

body {
    font-family: "WenJin Mincho Plane 0";
    font-weight: normal;
}
/* === 一、全局控制 === */
:root {
  /* 主要颜色变量 */
  --main-text-color: #a8a8a8; /* 主要文字颜色 */


  --shadow-color: transparent; /* 文字阴影颜色 */
  --chat-tint-color: transparent; /* 聊天区域背景颜色 */
  --blur-tint-color: rgba(255, 255, 255, 0.1); /* 毛玻璃背景颜色 */
  --border-color: rgba(255, 255, 255, 1); /* 边框颜色 */
  --user-mes-blur-tint-color: transparent; /* 用户聊天气泡背景 */
  --bot-mes-blur-tint-color: transparent; /* AI聊天气泡背景 */
  --blur-strength: 0px; /* 背景模糊强度 */
  --message-bg-alpha: 0; /* 消息背景透明度 */

  /* 聊天气泡底部背景层 - 新增 */
  --bubble-underlay-color: rgba(255, 255, 255, 0); /* 气泡背景透明度，改最后一个数字改成0.7都行 */
  --bubble-underlay-height: 100%; /* 气泡底部背景层高度 - 伪元素的一半 */

  --blur-strength: 0px; /* 背景模糊强度 */
  --message-bg-alpha: 0; /* 消息背景透明度 */

  /* 自定义变量 */
  --字体1: "不用填"; /* 主要字体 */
  --自定义思维链文案: "//"; /* 思维链自定义文案 */
  --自定义加载更多信息文案: "//"; /* 加载更多消息文案 */
  --自定义输入框文字: "//"; /* 输入框提示文字 */

  /* === 元素位置控制变量 === */
  /*头像位置🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧头像容器整体控制 */

  --avatar-w:  308px;   /* 容器宽度 */
  --avatar-h:  208px;   /* 容器高度 */

  /* 伪元素独立控制 */
  --pseudo-top: 100px; /* 伪元素顶部位置 */
  --pseudo-left: 50px; /* 伪元素水平位置 */
  --pseudo-width: 200px; /* 伪元素宽度 */
  --pseudo-height: 150px; /* 伪元素高度 - 调低避免重叠 */
  --pseudo-scale: 0.55; /* 伪元素缩放 */

  /* 头像在伪元素内定位 */
  --avatar-top: 65%; /* 头像在伪元素内的垂直位置 - 调整到右下角 */
  --avatar-left: 50%; /* 头像在伪元素内的水平位置 */
  --avatar-scale: 1; /* 头像缩放 */

  /* 三个信息元素独立控制？ */
  --info-top: 20px; /* 信息元素垂直位置 */
  --info-left: 20px; /* 信息元素水平位置 */
  --info-scale: 1; /* 信息元素缩放 */


  --mes-timer-top: 72px; /* 🧧计时器垂直位置 */
  --mes-timer-left: 23%; /* 🧧计时器水平位置 */
  --token-top: 65px; /* 🧧Token计数垂直位置 */
  --token-left: 30%; /* 🧧Token计数水平位置 */
  --mesid-top: 65px; /* 🧧楼层数垂直位置 */
  --mesid-left: 24.5%; /* 🧧楼层数水平位置 */
}



/* === 二、顶栏美化 === */
#top-settings-holder {
  position: relative; /* 关键：让伪元素相对它定位 */
  background: none !important; /* 本身不设背景 */
  box-shadow: none !important;
  border-bottom: 0px solid #FFDB80;
  height: 30px; /* 你想让顶栏多高就设多高 */
  overflow: visible !important; /* 允许溢出 */
}

/* 背景图伪元素：溢出显示 */
#top-settings-holder::before {
  content: "";
  position: absolute;
  top: -0px;      /* 向上溢出50px，可调 */
  left: 0;
  width: 100vw;
  height:50px;   /* 必须比90px高，才能“溢出” */
  background: url('https://iili.io/q0YNGna.png') no-repeat center top / cover;
  z-index: -1;     /* 不被毛玻璃盖住 */
  pointer-events: none;
}

#top-settings-holder::after {
  content: "";
  position: absolute;
  inset: 0;
  backdrop-filter: blur(0px); /* 你想模糊就加，不想就0 */
  z-index: 0; /* 夹在背景和图标之间 */
  pointer-events: none;
}

/* --- 顶部图标通用样式@毛毛雨 --- */
.drawer-icon::before {
    content: '';
    display: none;
}

.drawer-icon {
    filter: drop-shadow(0 0px 0px rgba(225, 182, 194, 0.2)) !important;
    opacity: 0 !important;
    display: flex;
    align-items: center;
    width: 28px;
    height: 28px;
    margin-top: 1px !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: transform 0.3s ease !important;
}


.drawer-icon:hover {
    opacity: 1!important;  /* 悬停显示 */
    transform: scale(1.25) rotate(5deg);
}

/* --- 各个功能按钮图标，代码来自@毛毛雨 --- */

/* 所有图标共用同一个背景图 */
#leftNavDrawerIcon,
#sys-settings-button .drawer-icon,
#advanced-formatting-button .drawer-icon,
#WI-SP-button .drawer-icon,
#user-settings-button .drawer-icon,
#backgrounds-drawer-toggle .drawer-icon,
#logo_block .drawer-icon,
#extensions-settings-button .drawer-icon,
#table_drawer_icon,
#persona-management-button .drawer-icon,
#rightNavDrawerIcon,
#horae_drawer_icon {
    background-image: url('https://iili.io/q0c3QBS.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

/* top-bar插件 */
#extensionTopBar {
    z-index: 500;
    margin-top: 18px !important;
    min-height: 40px;
}


/* 强制清除顶栏及父容器的黑色阴影 */
#top-settings-holder,
#top-bar, /* 顶栏父容器 */
.header-container, /* 可能的外层容器 */
.nav-bar { /* 通用导航栏容器 */
    box-shadow: none !important;
    -webkit-box-shadow: none !important;
    filter: drop-shadow(0 0 0 transparent) !important;
}
/* === 三、底栏美化 === */
/* 隐藏所有原始图标的伪元素 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
  display: none !important; /* 隐藏元素 */
}

/* 统一设置所有图标按钮样式 */
#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
  width: 10px; /* 图标宽度 */
  height: 10px; /* 图标高度 */
  background-size: contain; /* 背景图适应 */
  background-repeat: no-repeat; /* 不重复背景 */
  background-position: center; /* 背景图居中 */
  transition: transform 0.2s ease; /* 过渡动画 */
  font-size: 0; /* 隐藏文本 */
  border: none; /* 无边框 */
  background-color: transparent; /* 透明背景 */
}



/* 🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑🛑底栏按钮背景图片 */
#options_button { background-image: url('https://iili.io/qc8hRPj.png');
opacity: 0.1!important;
 } /* 菜单按钮 */
#extensionsMenuButton { background-image: url('https://iili.io/qc8hRPj.png'); 
opacity: 0.1!important;
} /* 扩展按钮 */
#send_but { background-image: url('https://iili.io/qc8hRPj.png'); 
opacity: 0.1!important;
} /* 发送按钮 */

/* 停止图标美化 */
#mes_stop {
  font-size: 0 !important; /* 隐藏文本 */
  width: 25px; /* 图标宽度 */
  height: 25px; /* 图标高度 */
  opacity: 0.3!important;
  background-image: url('https://iili.io/qc8hRPj.png'); /* 停止图标 */
  background-size: contain; /* 背景图适应 */
  background-repeat: no-repeat; /* 不重复背景 */
  background-position: center; /* 背景图居中 */
}
/*QR快捷回复*/
#quick-reply-rocket-button {
  font-size: 0 !important; /* 隐藏文本 */
  width: 10px; /* 图标宽度 */
  height: 10px; /* 图标高度 */
  opacity: 0.1!important;
  background-image: url('https://iili.io/qc8hRPj.png'); /* qr图标 */
  background-size: contain; /* 背景图适应 */
  background-repeat: no-repeat; /* 不重复背景 */
  background-position: center; /* 背景图居中 */
}

/* 底栏悬浮效果 */
#form_sheld {
  position: absolute; /* 绝对定位 */
  bottom: 0px; /* 底部间距 */
}

#send_form {
  width: 100%; /* 底栏宽度 */
}

.last_mes {
  margin-bottom: 50px !important; /* 最后消息底部间距 */
}

/* 底栏样式 */
/* 底栏样式 - 非等比拉伸填充 */
#send_form, body.no-blur #send_form {
  position: relative;
  background-image: url('https://iili.io/q0a3Yu4.png');
  background-size: cover;        /* 宽度100%，高度100% - 非等比拉伸 */
  background-position: left bottom;
  background-repeat: no-repeat;       /* 防止重复平铺 */
  border-radius: 0px 0px 0 0;
  background-color: rgba(0, 0, 0, 1) !important;
  padding: 7px 12px;
  backdrop-filter: blur(0px);
  -webkit-backdrop-filter: blur(0px);
  border-top: 0px solid rgba(3, 3, 3, 1);
  transition: all 1s ease;
}

/* 底栏图标间距 */
#rightSendForm, #leftSendForm {
  gap: 5px; /* 图标间距 */
}

/* 输入框样式 */
#send_textarea {
  clip-path: none !important; /* 完整显示输入框 */
  background-color: transparent;      /* 白底 */
  border: 0px solid #DFCFF0;      /* 灰色边框（四周） */
  box-shadow: none;            /* 无阴影 */
  border-radius: 16px;            /* 直角 */
  color: #9B8379!important;
}

/* 方案1：彻底关掉 */
#send_form:focus-within {
    outline: none !important;
    border: 0px solid #121212!important;
 /* 保持你自己设的边框 */
}

/* === 输入框左上角装饰图标 === */
#send_form::after {
  content: "";
  position: absolute;
  top: -1px;          /* 向上偏移，让图标一半露出 */
  left: 33%;        /* 向右偏移 */
  width: 40px;         /* 装饰图标大小 */
  height: 40px;
  background: url('https://iili.io/q0c3QBS.png') center/contain no-repeat;
  pointer-events: none;/* 不挡点击 */
  z-index: 10;         /* 保证在最上层 */
}

/*右上角装饰@nini*/

#top-bar::after {
    content: '';
    display: block;
    width: 100%;
    height: 28px;
    background-image: url("1https://iili.io/q2MlRDb.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: calc(100% - -2px) 0;   /* ← 只改这里 */
    margin-top: 25px;
    pointer-events: none;
    transform: scale(4);
    transform-origin: right top;
    z-index: 6;
}

/* === 四、聊天区域美化 === */
/* 聊天区域背景透明 */
#chat {
  background-color: transparent !important; /* 透明背景 */
  backdrop-filter: none !important; /* 无模糊 */
  -webkit-backdrop-filter: none !important; /* Safari兼容 */
  padding: 0 !important; /* 无内边距 */
}

/* 聊天滚动容器透明 */
#chat,
#chat > div,
.chat-scroll-container,
.chat-messages-container {
  background-color: transparent !important; /* 透明背景 */
  background-image: auto !important; /* 无背景图 */
  border: none !important; /* 无边框 */
  outline: none !important; /* 无轮廓 */
}

/* Firefox滚动条兼容 */
.chat-scroll-container {
  scrollbar-color:  transparent !important; /* 透明滚动条 */
}

/* 🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗🤗玲二改版聊天气泡 二改自@nini */
.mes {
    --w: 423px;          /* 🉐第一步改左边这个423数值直到气泡撑满你的屏幕🔴头尾图宽度 */
    --gap: -310px;         /* 🧧🧧两条消息间距 */
    --head-h: 308px;     /* 第二步修改左边这个327数值直到你的气泡没有断层🔴气泡头部图片和正文图片距离🧧🧧头图原高（占位用） */
    --foot-real: 40px;  /* 第三步（可选）尾图断层改这个🧧🧧尾图原高（偏移量用） */
    --foot-show: 202px;  /* 尾图你想显示的视觉高度，想调就改它 */

    max-width: var(--w);
    width: 100% !important;
    margin: calc(var(--head-h) + var(--gap)) auto var(--gap);
    position: relative;
    overflow: visible;
    background: none;
    border: none;
    box-shadow: none;

    /* 头图 */
    background-image: url("https://iili.io/qcLZQee.png");
    background-repeat: no-repeat;
    background-position: center top;
    background-size: 100% auto;

    padding-top: var(--head-h);
    padding-bottom: var(--foot-real); /* 仍用真实高度占位 */
    padding-left: 20px;
    padding-right: 0;
}

/* 中间平铺层（只裁自己） */
.mes::before {
    content: "";
    position: absolute;
    inset: var(--head-h) 0 var(--foot-real) 0; /* 裁剪线用真实高度 */
    background: url("https://iili.io/qcLbbXs.png") repeat-y;
    background-position:center 108px;
    background-size: 100% auto;
    z-index: -1;
    mask: linear-gradient(to bottom, transparent 0, black 1px, black 100%);
}

/* 尾图：尺寸与偏移量分离 */
.mes::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: calc(-1 * var(--foot-real)); /* 偏移仍用真实高度，保证拼接无缝 */
    height: var(--foot-show);            /* 视觉高度你想调就调 */
    background: url("https://iili.io/qcLtDvt.png") no-repeat center bottom / 100% var(--foot-show);
    z-index: 2;
    pointer-events: none;
}

/* === 头像容器😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡 === */
.mesAvatarWrapper .avatar {
  position: absolute !important;
  top: 76px;/*头像上下位置🧧🧧*/
  left: 27px;/*头像左右位置🧧🧧*/
  width: var(--avatar-w) !important;
  height: var(--avatar-h) !important;
  order: 1;
  margin: 0 !important;
  padding: 0 !important;
  display: block !important;
  z-index: -6;
}

/* === 头像框伪元素：同步尺寸 === */
.mes .mesAvatarWrapper::after {
  content: '' !important;
  position: absolute !important;

  /* 同步头像位置 */
  top: 76px;
  left: 27px;

  width: var(--avatar-w);
  height: var(--avatar-h);

  /* 🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴🔴头像效果GIF，如果你想更换或去除效果直接修改下面的链接，看不懂你就叫ai
提示：只能使用黑底白颜色的动图
其他效果存放：
①飘雪1：https://iili.io/qFCgWPI.gif
②飘雪2：https://iili.io/qFCy1Np.gif */
  background-image: url('留空') !important;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;

  /* 融合效果 */
  mix-blend-mode: screen;

  pointer-events: none;
  z-index: -2;
}


/*控制头像显示区域@栗子*/
#chat .mes .avatar img {
    width: 100% ;  /* 自己设置 */
    height: 100% ; /* 自己设置 */
    object-fit: cover;
    object-position: center 40%; /* 🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧🧧数值越小，显示区域越靠上，也可以把center 40%换成百分比，比如：20% 80% */
    border-radius: 0 !important;
    box-shadow: none !important;
}
/*隐藏收藏黄圈@Little YE*/
.character_select.is_fav .avatar {
  outline: none !important;
}
/*头像-------收藏角色、角色详情、user头像、角色选择*/
.avatar-container .avatar img,
.character_select > .avatar img,
.inline_avatar.avatar img,
#avatar_div_div img {
    border: 2px solid #4f2517;
    border-bottom: 6px solid #4f2517;
    box-shadow: 0px 0px 0 0 rgba(134, 37, 137, 0.3);
