}

/* 为每个元素单独设置位置 */
.mes_timer {
  top: var(--mes-timer-top, 20px) !important; /* 计时器垂直位置 */
  left: var(--mes-timer-left, 120px) !important; /* 计时器水平位置 */
}

.tokenCounterDisplay {
