}

/* === 文字容器调整 === */
.mes .mes_block {
  width: 98% !important; /* 文字区域宽度 */
  text-align: left !important; /* 文字左对齐 */
  margin: 0 !important; /* 无边距 */
  padding: 0px !important; /* 内边距 */
  background: transparent !important; /* 透明背景 */
  border-radius: 0px !important; /* 无圆角 */
  position: relative !important; /* 相对定位 */
  z-index: 999 !important; /* 文字层级 */
  margin-top: calc(var(--pseudo-height, 310px) + var(--avatar-container-top, 0px) + 0px) !important; /* 根据伪元素高度和容器位置动态调整间距 */
}/* === 文字容器调整 === */
/* === 文字容器调整 === */
.mes .mes_block {
  width: 84% !important;
  text-align: left !important;
  margin: 50px 0 0px 25px !important;   /* 🧧🧧🧧🧧上左下右边距，好像只有左右有效🛑🛑🛑🛑🛑🛑🛑 */
  padding: 0 !important;
  background: transparent !important;
  border-radius: 0 !important;
  position: relative !important;
  z-index: 999 !important;
