/* === 六、滚动条和滑动条美化@这对吗 === */
::-webkit-scrollbar {
    width: 0px; /* 🛑滚动条整体宽度，自调 */
    background-color: transparent; 
}
::-webkit-scrollbar-track {
    background-color: transparent; 
}
::-webkit-scrollbar-thumb {
  /* 方向（to bottom=从上到下）+ 颜色列表（用逗号分隔） */
  background-image: linear-gradient(to bottom, #FFCAD4, #FFCAD4, #FFCAD4);
  /* 如需渐变，比如上浅下深：linear-gradient(to bottom, #64a4c8, #4287a8) */
