input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    background: transparent;
    cursor: pointer;
}

/* 2. 🛑设计滑块的“轨道”左右滑块 */
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 6px; /* 轨道的粗细 */
    /* 轨道的背景现在是一个静态的、完整的渐变色，✨︎渐变颜色自调下边两个数值，调整原理和上边那个一样 ✨︎ */
    background: linear-gradient(to right, #4f2517,#4f2517); 
    border-radius: 0px;
    border: 0px solid rgba(255, 255, 255, 0.1);
}

/* 3. 设计滑块的“手柄” (Thumb) - 使用自定义图标 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;    
    margin-top: -17px; /* ✨︎图标（手柄）的上下距离，改了大小就要改这里哦，确保滑动的图标在滑动条上 ✨︎ */
    height: 35px; /* 高度 */
    width: 35px; /* 宽度 */

    /* ✨︎图标替换，自改✨︎ */
    background-image: url('https://iili.io/q0Dtsx2.png');
    background-size: contain; /* 确保图标完整显示，不被拉伸 */
    background-repeat: no-repeat;
    background-position: center;

    /* 移除所有可能导致“变淡”的默认样式 */
    background-color: transparent; 
    border: none;
    border-radius: 0;
    box-shadow: none;
    transition: transform 0.2s ease; /* 保留悬停放大动画 */
}
/* 去除左右滑块阴影@玲 */
