========= 顶部图片高度变量（统一调） ========== */
:root {
  --head-h: 5px;          /* 顶部图片高度，必须和原来 --head-h 一致 */
  --name-x: 88%;            /* 🛑名字水平位置（% / px / vw 都行） */
