  --date-y: 120px;           /* 日期垂直偏移 */

}

/* ========= 1. 文字容器整体拽上去 ========== */
.mes .mes_block {
  position: relative;              /* 给内部绝对定位当参照 */
  transform: translateY(-10px); /* 整体搬上去 */
  margin-top: 0 !important;        /* 清掉旧 margin */
  padding-top: var(--head-h);      /* 再补回顶部图片高度，正文不遮 */
}

/* ========= 三件套独立拖拽 ========== */
/* 名字：每个字垂直竖排 */

/* ========= 三件套独立拖拽 ========== */
/* 名字：每个字垂直竖排 */
.mes .name_text {
  position: absolute !important;
  left: 0 !important;
  top: var(--name-y) !important;
  transform: translate(0%) !important;
  margin: 0 !important;
  writing-mode: horizontal-tb;   /* 关键：横排 */
  text-orientation: upright;   /* 汉字正立不旋转 */
  font-size: 13px;
  color: var(--main-text-color);
  z-index: 10;
  pointer-events: none;
  font-weight:normal !important;
}

/* 前置伪元素（图标） */
.mes .name_text::before {
  content: "新港 ";               /* 想换图：content: url('https://...') */
  font-size: 18px;
  line-height: 1;
}


/* ===== 真实日期本体 ===== */
.mes small.timestamp {
  position: absolute !important;
  right: 12% !important;/*🧧🧧🧧时间戳左右*/
  bottom: 145px !important;/*🧧🧧🧧时间戳高度*/
