  font-weight: normal !important;
  opacity:1 !important;
}


/* ===== 🛑🛑🛑🛑编辑消息图标（小铅笔）独立定位变量 ===== */
:root{
  --icon-right:48px;   /* 🧧🧧离右边距离 */
  --icon-top: 282px;     /* 🧧🧧离顶部距离 */
