}

/* 让整条按钮栏脱离文档流并贴边 */
.mes .mes_buttons{
  position: absolute !important;
  top: var(--icon-top) !important;
  right: var(--icon-right) !important;
  display: flex;
  flex-direction:row ;   /* 纵向排列column，想横向改成 row */
  gap: var(--icon-gap);
  z-index: 20;
}

/* 去掉原版多余 margin */
.mes .mes_buttons .mes_button{
  margin: 0 !important;
}
/* ===== 详细编辑栏最终版：区分 user / char，且不受思维链影响 ===== */
:root{
  /* 微调口：觉得整体偏上就改小，偏下就改大 */
  --edit-bar-offset-top: 306px;   /* 负值 = 贴在正文盒外顶部；0 = 贴内顶部；正值 = 悬在上方更远 */
}

/* 1. 让正文盒成为统一参照 */
.mes .mes_text{
  position: relative !important;   /* 只当坐标系，不碰 padding/margin */
}

/* 2. 详细编辑栏绝对贴顶 + 水平居中 */
.mes_edit_buttons{
  position: absolute !important;
  top: var(--edit-bar-offset-top) !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  gap: 6px;
  z-index: 999;          /* 保证在最上层 */
  pointer-events: all;   /* 确保可点 */
  flex-direction: row;
  column-gap: 5px;
  float: right;
  cursor: pointer;
  padding-bottom: 5px;
  filter: none; /*移除阴影@易碎蝶*/
  transition: 0.3s ease-in-out;
}
.mes_edit_down.menu_button.fa-solid.fa-chevron-down.interactable.disabled {
    filter: none !important;
}

/* 3. 其余所有按钮栏一律隐藏，防止双份 */
.mes > .mes_buttons,
.mes .mes_block > .mes_buttons{
  display: none !important;
}
/* ===== 详细编辑栏 → 只定位，不抢 display ===== */
:root{
  --edit-bar-top: 50px;   /* 想悬在正文盒上方 30px；贴顶就写 0 */
}

/* 只在“编辑中”状态才让它可见 + 定位 */
.mes.edit-mode .mes_edit_buttons{
  position: absolute !important;
  top: var(--edit-bar-top) !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
