}

/* 1. 把之前所有定位全清掉 */
.mes_reasoning,
.mes_reasoning_summary{
  position: relative !important;
  top: auto !important; left: auto !important; right: auto !important; bottom: auto !important;
  transform: translateY(var(--rs)) !important;   /* 唯一偏移口 */
  margin-left: 26% !important;                     /* 思维链左右位置🛑水平居中 */
  width: 90% !important;
  max-width: 480px !important;
  z-index: 5 !important;                         /* 保证在文字层上方 */
}

/* 2. 让下拉箭头也同步走，不要分裂 */
