/* ===== 弹窗本体 ===== */
dialog.popup.popup--animation-fast {
    background: url(https://iili.io/q0tTnnI.png)center/cover;          /* 窗口背景 */
    border: 0px solid #121212;   /* 边框 */
    border-radius: 0px;
    box-shadow: none;            /* 去除阴影 */
    color: #9B8379;                 /* 默认文字深灰，可自己改 */
}

/* ===== 正文容器 ===== */
dialog.popup .popup-content,
dialog.popup .popup-body {
    background: transparent;         /* 正文区域底色 */
}

/* ===== 红色按钮（是） ===== */
dialog.popup .popup-button-ok {
    background: #884931!important;         /* 底色 */
    color: #000;              /* 字体颜色 */
    border: none;
    border-radius: 0px;
    padding: 6px 16px;
    cursor: pointer;
    transition: background .2s;
}
dialog.popup .popup-button-ok:hover {
    background: #84931;         /* 悬停稍深 */
}

/* ===== 白色按钮（否） ===== */
dialog.popup .popup-button-cancel {
    background: #000!important;         /* 底色 */
    color: #884931!important;              /* 字体颜色 */
    border: 0.5px solid #884931!important;  /* 边框 */
    border-radius: 0px;
    padding: 6px 16px;
    cursor: pointer;
    transition: background .2s, color .2s;
}
dialog.popup .popup-button-cancel:hover {
    background: #884931;
    color: #ffffff;
}

/* ===== 关闭图标（如有） ===== */
dialog.popup .popup-button-close {
    color: #884931;
}
/* ===== 漏掉的 textarea 单独补白 ===== */
textarea.alternate_greeting_text {
    background: transparent !important;   /* 背景颜色 */
    border: 0px solid #121212 !important;
    border-radius: 0px;
    color: #9B8379;                      /* 文字颜色，可改 */
    padding: 8px;
}
/* 统一白底 1px 边框 */
input[type="search"].text_pole,
input[type="text"].text_pole,
textarea.text_pole {
    background: transparent !important;
    border: 0px solid #9CBEDD !important;
    border-radius: 0px;
    padding: 6px 8px;
    color: #9B8379;          /* 文字颜色，想改就换 */
}
.completion_prompt_manager_prompt span span span {
    filter: none !important;
}

/* 左箭头 */
.swipe_left {
  background-image: url("https://iili.io/q0poF1t.png");
  transform: translateY(-38px) translateX(56px);
  opacity: 0.3;
}

/* 右箭头 */
.swipe_right {
  background-image: url("https://iili.io/q0pxhV2.png");
  transform: translateY(-38px) translateX(-75px);
  opacity: 0.3;         /* 你原来就有透明度，保留 */
}
/* 直接找到原图标的具体选择器，用更具体的选择器覆盖 */
[class*="swipe_left"]::before,
[class*="swipe_right"]::before {
  display: none !important;
  content: none !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
}
/*🧧翻页页数*/
.swipes-counter {
    z-index: 10;
    color: #9B8379 !important;
    transform: translateY(-70px) translateX(-73px);
}
/*去除小黑点@nini*/
#send_textarea {
  resize: none; 
}
/* 让所有 <hr> 变成 2px #b3b3b3 灰色直线 */
hr {
    all: unset !important;          /* 1. 抹掉浏览器默认样式 */
    display: block !important;      /* 2. 块级盒子，方便上下留空 */
    position: relative !important;  /* 3. 给伪元素当定位包含块 */
    height: 62px !important;        /* 4. 整条分割线的高度，写死 32px（想改就改这里） */
    margin: 0 0 10px 0 !important;      /* 5. 上下留空 20px，左右先写 0，后面伪元素自己留边距 */
    border: none !important;        /* 6. 彻底隐藏原来的线 */
    overflow: hidden !important;    /* 7. 防止伪元素溢出 */
}

/* 8. 真正贴图的地方 */
hr::after {
    content: "" !important;
    position: absolute !important;
    left: 0px !important;          /* 左边距，想调就改这里 */
    right: 0px !important;         /* 右边距，想调就改这里 */
    top: 50% !important;
    transform: translateY(-50%) !important;  /* 垂直居中 */
    height: 100% !important;        /* 占满父级高度，也就是 32px */
    background: url("https://iili.io/q1qYnnf.png") center/contain no-repeat !important;
    /* contain 保证图不变形；左右没盖到的地方自然留白 */
}

/* 复选框@蘑菇蟑螂汤 */
input[type="checkbox"] {
    -webkit-appearance: none;   /* 去掉默认样式 */
    appearance: none;
    background: url(https://iili.io/q1d7OL7.png); /* 未选图 */
    background-size: contain;
    border: none;
    box-shadow: none;
    border-radius: 50%;
    width: 1em;
    height: 1em;
    outline: none;
    filter: none!important;
}
input[type="checkbox"]:checked {
    background: url(https://iili.io/q0bPk1s.png); /* 已选图 */
    background-size: contain;
    background-repeat: no-repeat;
}
/* 隐藏浏览器自带的白色对勾 */
input[type="checkbox"]::before,
input[type="checkbox"]::-webkit-check {
    content: none !important;
    display: none !important;
}


/* ===== 强制去圆角：气泡本身 ===== */
.mes,
.mes::before,
.mes::after,
.mes .mes_block,
.mes .mes_text {
    border-radius: 0 !important;
    overflow: visible !important;   /* 防止某些主题再裁掉尖角 */
}


